# Test the equation a_{a_{a_p}} = a_{p+1} + 1 for p=0, 1, 2
# Sequence elements must be non-negative integers.
# We test the sequence: a_0=1, a_1=0, a_2=0
a = {0: 1, 1: 0, 2: 0}

def get_a(index, sequence):
    # Helper function to retrieve a_i, ensuring index is valid (non-negative)
    if index < 0:
        return None # Indicates an invalid index
    return sequence.get(index)

def check_equation(a, p):
    try:
        # Check index validity for a_p, a_{a_p}, a_{a_{a_p}}
        val_ap = get_a(p, a)
        if val_ap is None:
            return "FAIL: Index p={} is negative.".format(p)

        # Check index validity for a_{a_p}
        val_a_ap = get_a(val_ap, a)
        if val_a_ap is None:
            return "FAIL: Index a_p={} is negative.".format(val_ap)

        # Check index validity for a_{a_{a_p}}
        val_a_a_ap = get_a(val_a_ap, a)
        if val_a_a_ap is None:
            return "FAIL: Index a_{a_p}={}_ is negative.".format(val_ap)

        # Check RHS index validity
        if p + 1 not in a:
             return "FAIL: Index p+1={} is not defined in the given sequence subset.".format(p + 1)

        # Calculate LHS
        LHS = val_a_a_ap

        # Calculate RHS
        RHS = a[p + 1] + 1

        if LHS == RHS:
            return "SUCCESS"
        else:
            return "FAIL: LHS={} != RHS={}".format(LHS, RHS)

    except KeyError as e:
        return "FAIL: Index required by calculation not defined in sequence subset: {}".format(e)

print("--- Testing Case: a_0=1, a_1=0, a_2=0 ---")
p_tests = [0, 1, 2]
for p in p_tests:
    result = check_equation(a, p)
    print("Test p={}: {}".format(p, result))

